    match => match.includes('err ') ? 'err instanceof Error ? err.message' : 'error instanceof Error ? error.message');

  if (content !== original) {
    fs.writeFileSync(file, content, 'utf8');
  }
}

function processAllFiles(dir) {
  fs.readdirSync(dir).forEach(f => {
