      cell: (row: any) => <span className="text-gray-700">{row.worker}</span>,
    },
    {
      header: 'Service Category',
      accessorKey: 'category',
      cell: (row: any) => <Badge variant="outline" className="bg-gray-50">{row.category}</Badge>,
    },
    {
      header: 'Status',
      accessorKey: 'status',
