          {row.status.replace(/_/g, ' ')}
        </Badge>
      ),
    },
    {
      header: 'Booking Date',
      accessorKey: 'date',
    },
    {
      header: 'Amount',
      accessorKey: 'amount',
      cell: (row: any) => <span className="font-bold text-gray-900">{row.amount}</span>,
    },
  ];

  return (
    <DataTable data={data} columns={columns} searchable={true} searchKey="id" filterable={true} />
  );
}

