}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { auth } from '@/lib/auth';
import { sendNotification } from '@/services/notification';
import { approveWorker, rejectWorker, suspendWorker, requestMoreInfo } from '@/services/verification';
export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  try {
    const session = await auth();
    const userRole = session?.user?.role;
    console.log(`[AUTH DEBUG] PATCH /api/admin/workers/[id] - UserID: ${session?.user?.id}, Role: ${userRole}, CoopID: ${session?.user?.cooperativeId}`);
    if (!session?.user || (userRole !== 'ADMIN' && userRole !== 'COOPERATIVE_ADMIN' && userRole !== 'FEDERATION_ADMIN')) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const resolvedParams = await params;
    const workerId = resolvedParams.id;
    const contentType = req.headers.get('content-type') || '';
    if (!contentType.includes('application/json')) {
      return NextResponse.json({ error: 'Content-Type must be application/json' }, { status: 400 });
    }

    let body;
    try {
      body = await req.json();
    } catch (e) {
      return NextResponse.json({ error: 'Invalid or empty JSON body' }, { status: 400 });
    }

    if (!body || typeof body !== 'object') {
      return NextResponse.json({ error: 'JSON body must be an object' }, { status: 400 });
    }

    const { status, reason } = body;
    const validStatuses = ['PENDING', 'UNDER_REVIEW', 'VERIFIED', 'REJECTED', 'SUSPENDED', 'MORE_INFO_REQUIRED'];
    if (!status || !validStatuses.includes(status)) {
      return NextResponse.json({ error: 'Invalid verification status' }, { status: 400 });
    }

    if ((status === 'REJECTED' || status === 'SUSPENDED' || status === 'MORE_INFO_REQUIRED') && !reason?.trim()) {
      return NextResponse.json({ error: `A reason is required when status is ${status}` }, { status: 400 });
    }

    const worker = await prisma.worker.findUnique({
      where: { id: workerId },
      include: { user: true }
    });

    if (!worker) {
      return NextResponse.json({ error: 'Worker not found' }, { status: 404 });
    }

    console.log(`[AUTH DEBUG] Worker CoopID: ${worker.cooperativeId}`);

    if (userRole === 'COOPERATIVE_ADMIN' && worker.cooperativeId !== session.user.cooperativeId) {
      return NextResponse.json({ error: 'Forbidden: Worker belongs to a different cooperative' }, { status: 403 });
    }

    let updatedWorker;
    
    if (status === 'VERIFIED') {
      updatedWorker = await approveWorker(workerId, session.user.id as string, reason);
    } else if (status === 'REJECTED') {
      updatedWorker = await rejectWorker(workerId, session.user.id as string, reason || 'Rejected by Admin');
    } else if (status === 'SUSPENDED') {
      updatedWorker = await suspendWorker(workerId, session.user.id as string, reason || 'Suspended by Admin');
    } else if (status === 'MORE_INFO_REQUIRED') {
      updatedWorker = await requestMoreInfo(workerId, session.user.id as string, reason || 'More info required');
    } else {
      updatedWorker = await prisma.worker.update({
        where: { id: workerId },
        data: { verificationStatus: status }
      });
    }

    let title = 'Verification Update';
    let msg = `Your profile verification status has been updated to ${status}.`;
    if (status === 'VERIFIED') {
      title = 'Profile Verified!';
      msg = 'Congratulations! Your profile has been verified and you can now receive jobs.';
    } else if (status === 'REJECTED') {
      title = 'Profile Rejected';
      msg = `Your profile application was rejected. Reason: ${reason || 'Not specified'}`;
    }

    await sendNotification(worker.user.id, 'WORKER', title, msg, { workerId, status });

    return NextResponse.json({ success: true, worker: updatedWorker });
  } catch (error) {
    console.error('Admin Worker Update Error:', error);
    return NextResponse.json({ error: (error instanceof Error ? error.message : "Unknown error") }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { auth } from '@/lib/auth';
import { createBooking } from '@/services/booking';
import { ensureServiceCategories } from '@/lib/reference-data';

export async function GET(req: NextRequest) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const customerId = session.user.customerId;
    const workerId = session.user.workerId;
    const role = session.user.role;

    const whereClause: any = {};
    if (role === 'CUSTOMER' && customerId) {
      whereClause.customerId = customerId;
    } else if ((role === 'WORKER' || role === 'HELPER') && workerId) {
      whereClause.workerId = workerId;
    } else if (role === 'COOPERATIVE_ADMIN') {
      const cooperativeId = session.user.cooperativeId;
      if (cooperativeId) {
        whereClause.worker = { cooperativeId };
      }
    }

    const { searchParams } = new URL(req.url);
    const status = searchParams.get('status');
    if (status) {
      whereClause.status = status;
    }

    const bookings = await prisma.booking.findMany({
      where: whereClause,
      include: {
        category: true,
        worker: {
          include: {
            user: { select: { id: true, name: true, phone: true, avatar: true } },
            cooperative: true,
          },
        },
        customer: {
          include: {
            user: { select: { id: true, name: true, phone: true } },
          },
        },
        payment: true,
        invoice: true,
        rating: true,
      },
      orderBy: { createdAt: 'desc' },
    });

    return NextResponse.json(bookings);
  } catch (error) {
    console.error('Bookings GET Error:', error);
    return NextResponse.json({ error: (error instanceof Error ? error.message : "Unknown error") || 'Failed to fetch bookings' }, { status: 500 });
  }
}

export async function POST(req: NextRequest) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ success: false, error: 'Unauthorized', code: 'UNAUTHORIZED' }, { status: 401 });
    }

    const body = await req.json();
    let customerId = session.user.customerId;
    if (!customerId) {
      // Find or create customer record for this user
      console.time('[booking] customer lookup');
      const customer = await prisma.customer.findUnique({
        where: { userId: session.user.id },
      });
      console.timeEnd('[booking] customer lookup');
      if (customer) {
        customerId = customer.id;
      } else {
        const newCustomer = await prisma.customer.create({
          data: {
            userId: session.user.id || 'default-user',
            city: body.city || 'Unspecified',
            state: body.state || 'Unspecified',
          },
        });
        customerId = newCustomer.id;
      }
    }

    const {
      workerId,
      categoryId,
      description,
      scheduledDate,
      scheduledTime,
      estimatedPrice,
      address,
      latitude,
      longitude,
      isEmergency,
    } = body;

    if (!workerId || !categoryId) {
      return NextResponse.json({ success: false, error: 'workerId and categoryId are required', code: 'MISSING_FIELDS' }, { status: 400 });
    }

    // Removed ensureServiceCategories() from the hot path to avoid 10 sequential upserts on every booking

    console.time('[booking] category check');
    const categoryExists = await prisma.serviceCategory.findUnique({
      where: { id: categoryId }
    });
    console.timeEnd('[booking] category check');
    
    if (!categoryExists) {
      return NextResponse.json({ success: false, error: 'Selected service category is no longer available. Please select another service.', code: 'INVALID_CATEGORY' }, { status: 400 });
    }

    if (!customerId) {
      return NextResponse.json({ success: false, error: 'Could not resolve customer ID', code: 'CUSTOMER_MISSING' }, { status: 400 });
    }

    const reqId = Math.random().toString(36).substring(7);
    console.time(`[booking] createBooking function ${reqId}`);
    const booking = await createBooking({
      customerId,
      workerId,
      categoryId,
      description: description || 'Service booking',
      scheduledDate: scheduledDate ? new Date(scheduledDate) : new Date(),
      scheduledTime: scheduledTime || '10:00 AM',
      estimatedPrice: estimatedPrice ? parseFloat(estimatedPrice) : 350,
      address: address || 'Service Location Not Provided',
      latitude: latitude ? parseFloat(latitude) : undefined,
      longitude: longitude ? parseFloat(longitude) : undefined,
      isEmergency: !!isEmergency,
    });
    console.timeEnd(`[booking] createBooking function ${reqId}`);

    if (address && customerId) {
      try {
        const normalizedAddress = address.toLowerCase().trim();
        const existingLocations = await prisma.customerLocation.findMany({ where: { customerId } });
        const duplicate = existingLocations.find(l => l.address.toLowerCase().trim() === normalizedAddress);
        if (!duplicate) {
          await prisma.customerLocation.create({
            data: {
              customerId,
              address: address,
              city: body.city || 'Ahmedabad',
              state: body.state || 'Gujarat',
              latitude: latitude ? parseFloat(latitude) : null,
              longitude: longitude ? parseFloat(longitude) : null,
              isDefault: existingLocations.length === 0
            }
          });
        }
      } catch (locErr) {
        console.error('Failed to save customer location history:', locErr);
      }
    }

    const imageUrls = body.imageUrls;
    if (imageUrls && Array.isArray(imageUrls) && imageUrls.length > 0) {
      await prisma.jobProof.createMany({
        data: imageUrls.map((url: string) => ({
          bookingId: booking.id,
          workerId: booking.workerId,
          type: 'BEFORE',
          imageUrl: url,
          caption: 'Customer uploaded BEFORE photo during booking',
          latitude: latitude ? parseFloat(latitude) : undefined,
          longitude: longitude ? parseFloat(longitude) : undefined,
        }))
      });
    }

    return NextResponse.json({ success: true, booking }, { status: 201 });
  } catch (error) {
    console.error('Booking Creation Error:', error);
    
    let errorCode = 'INTERNAL_ERROR';
    let status = 500;
    if ((error instanceof Error ? error.message : "Unknown error") === 'Worker not found') { errorCode = 'WORKER_NOT_FOUND'; status = 404; }
    if ((error instanceof Error ? error.message : "Unknown error").includes('not currently eligible')) { errorCode = 'WORKER_UNAVAILABLE'; status = 403; }
    if ((error instanceof Error ? error.message : "Unknown error").includes('no longer available for the selected time')) { errorCode = 'SCHEDULING_CONFLICT'; status = 409; }
    
    return NextResponse.json({ success: false, error: (error instanceof Error ? error.message : "Unknown error") || 'Failed to create booking', code: errorCode }, { status });
  }
}

