'use client';

import { useState, useEffect, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Card, CardContent } from '@/components/ui/card';
import { MatchScore } from '@/components/shared/match-score';
import { PriceEstimate } from '@/components/shared/price-estimate';
import { VoiceInput } from '@/components/shared/voice-input';
import { ArrowLeft, Check, Upload, Calendar as CalendarIcon, Clock, ShieldCheck, MapPin, Sparkles } from 'lucide-react';
import { toast } from 'sonner';

function BookServiceContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [bookingData, setBookingData] = useState({
    description: '',
    address: '',
    latitude: null as number | null,
    longitude: null as number | null,
    date: (() => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; })(),
    time: '11:00 AM',
    workerId: null as string | null,
    categoryId: 'cat-ac',
    categoryName: 'AC Repair',
    estimatedPrice: 450,
    isEmergency: false,
    imageUrls: [] as string[],
  });

  useEffect(() => {
    const q = searchParams.get('query');
    if (q) {
      setBookingData((prev) => ({ ...prev, description: q }));
    }
  }, [searchParams]);

  const [aiAnalysis, setAiAnalysis] = useState<any>(null);
  const [matchedWorkers, setMatchedWorkers] = useState<any[]>([]);
  const [selectedWorker, setSelectedWorker] = useState<any>(null);
  const [savedLocations, setSavedLocations] = useState<any[]>([]);

  useEffect(() => {
    fetch('/api/customer/locations')
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) setSavedLocations(data);
      })
      .catch(err => console.error('Failed to load locations', err));
  }, []);

  const stepTitles = [
    'Describe Problem',
    'AI Concierge',
    'Service Location',
    'Select Worker',
    'Schedule Time',
    'Fair Price',
    'Confirm Booking',
  ];

  const totalSteps = 7;

  const nextStep = () => setStep((prev) => Math.min(prev + 1, totalSteps));
  const prevStep = () => setStep((prev) => Math.max(prev - 1, 1));

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const toastId = toast.loading('Uploading photo...');
    try {
      const formData = new FormData();
      formData.append('file', file);
      
      const uploadRes = await fetch('/api/upload?type=public', {
        method: 'POST',
        body: formData,
      });
      const uploadData = await uploadRes.json();
      if (!uploadRes.ok) throw new Error(uploadData.error || 'Upload failed');
      
      setBookingData((prev) => ({ ...prev, imageUrls: [...(prev.imageUrls || []), uploadData.url] }));
      toast.success('Photo attached!', { id: toastId });
    } catch (err) {
      toast.error((err instanceof Error ? err.message : "Unknown error") || 'Photo upload failed', { id: toastId });
    } finally {
      e.target.value = ''; // reset
    }
  };

  const handleAnalyze = async () => {
    if (!bookingData.description.trim()) return toast.error('Please describe what you need');
    setLoading(true);
    try {
      const res = await fetch('/api/ai/concierge', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: bookingData.description }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'AI analysis failed');

      setAiAnalysis(data.analysis);
      setBookingData((prev) => ({
        ...prev,
        categoryId: data.analysis.categoryId,
        categoryName: data.analysis.category,
        isEmergency: data.analysis.urgency === 'EMERGENCY',
        estimatedPrice: data.category?.basePrice || 450,
      }));
      nextStep();
    } catch (err) {
      toast.error((err instanceof Error ? err.message : "Unknown error") || 'AI analysis failed');
    } finally {
      setLoading(false);
    }
  };

  const handleMatchWorkers = async () => {
    if (!bookingData.address.trim()) return toast.error('Please enter an address');
    setLoading(true);

    let lat = bookingData.latitude;
    let lng = bookingData.longitude;

    if (lat === null || lng === null || isNaN(lat) || isNaN(lng)) {
      try {
        const position = await new Promise<GeolocationPosition>((resolve, reject) => {
          if (!navigator.geolocation) {
            reject(new Error('Geolocation not supported'));
          } else {
            navigator.geolocation.getCurrentPosition(resolve, reject, { timeout: 10000 });
          }
        });
        lat = position.coords.latitude;
        lng = position.coords.longitude;
      } catch (geoError) {
        try {
          const res = await fetch(`https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(bookingData.address)}&format=json&limit=1`);
          const geoData = await res.json();
          if (geoData && geoData.length > 0) {
            lat = parseFloat(geoData[0].lat);
            lng = parseFloat(geoData[0].lon);
          } else {
            throw new Error('Address not found');
          }
        } catch (apiError) {
          setLoading(false);
          return toast.error('Could not find location. Please enter a valid address.');
        }
      }
    }

    try {
      const res = await fetch('/api/matching', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          categoryId: bookingData.categoryId,
          urgency: bookingData.isEmergency ? 'EMERGENCY' : 'NORMAL',
          latitude: lat,
          longitude: lng,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Matching failed');

      const matches = Array.isArray(data) ? data : [];
      setMatchedWorkers(matches);
      if (matches.length > 0) {
        setSelectedWorker(matches[0]);
        setBookingData((prev) => ({
          ...prev,
          workerId: matches[0].worker?.id || matches[0].id,
          estimatedPrice: matches[0].estimatedPrice || prev.estimatedPrice,
          latitude: lat,
          longitude: lng,
        }));
      } else {
        setBookingData((prev) => ({ ...prev, latitude: lat, longitude: lng }));
      }
      nextStep();
    } catch (err) {
      toast.error((err instanceof Error ? err.message : "Unknown error") || 'Failed to match workers');
    } finally {
      setLoading(false);
    }
  };

  const handleConfirm = async () => {
    if (!bookingData.workerId || !bookingData.date || !bookingData.time) {
      return toast.error('Please complete all booking steps');
    }
    setLoading(true);
    try {
      const res = await fetch('/api/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          workerId: bookingData.workerId,
          categoryId: bookingData.categoryId,
          description: bookingData.description,
          scheduledDate: bookingData.date,
          scheduledTime: bookingData.time,
          estimatedPrice: bookingData.estimatedPrice,
          address: bookingData.address,
          latitude: bookingData.latitude,
          longitude: bookingData.longitude,
          isEmergency: bookingData.isEmergency,
          imageUrls: bookingData.imageUrls,
        }),
      });
      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data.error || 'Booking failed');
      }

      toast.success(`Booking Confirmed! Security PIN: ${data.booking.servicePin}`);
      router.push(`/customer/bookings/${data.booking.id}`);
    } catch (err) {
      toast.error((err instanceof Error ? err.message : "Unknown error") || 'Booking failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col gap-6 p-4 pb-28 md:p-8 max-w-2xl mx-auto w-full min-h-[calc(100vh-4rem)]">
      <header className="flex items-center gap-4 mb-2">
        {step > 1 && (
          <Button variant="ghost" size="icon" onClick={prevStep} className="shrink-0 h-10 w-10 rounded-xl hover:bg-secondary">
            <ArrowLeft className="h-5 w-5" />
          </Button>
        )}
        <div className="flex-1">
          <div className="flex justify-between items-center text-xs font-semibold mb-2">
            <span className="text-foreground flex items-center gap-1.5">
              <span className="w-2 h-2 rounded-full bg-primary" />
              Step {step} of {totalSteps}: <span className="text-primary">{stepTitles[step - 1]}</span>
            </span>
            <span className="text-primary font-bold">{Math.round((step / totalSteps) * 100)}%</span>
          </div>
          <div className="h-2 bg-secondary rounded-full overflow-hidden border border-border/40">
            <div
              className="h-full bg-primary transition-all duration-300 rounded-full"
              style={{ width: `${(step / totalSteps) * 100}%` }}
            />
          </div>
        </div>
      </header>

      <div className="flex-1">
        {step === 1 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-right-4">
            <h1 className="text-2xl font-bold">What do you need help with?</h1>
            <p className="text-muted-foreground">Describe your problem in detail, or use voice input in English, Hindi, or Gujarati.</p>

            <div className="relative">
              <label htmlFor="problem-description" className="sr-only">Problem Description</label>
              <Textarea
                id="problem-description"
                name="description"
                autoComplete="off"
                value={bookingData.description}
                onChange={(e) => setBookingData({ ...bookingData, description: e.target.value })}
                placeholder="E.g., My AC cooling is very low and making a strange buzzing sound. Need urgent checkup..."
                className="min-h-[150px] text-base p-4"
              />
              <div className="absolute right-4 bottom-4">
                <VoiceInput onTranscription={(text) => setBookingData({ ...bookingData, description: text })} />
              </div>
            </div>

            <label htmlFor="booking-photo" className="sr-only">Upload Photo</label>
            <input type="file" name="booking-photo" accept="image/*" id="booking-photo" className="hidden" onChange={handlePhotoUpload} />
            <Button
              variant="outline"
              className="w-full gap-2 h-12 border-dashed"
              onClick={() => document.getElementById('booking-photo')?.click()}
            >
              <Upload className="h-4 w-4" />
              Attach Photos {bookingData.imageUrls?.length > 0 ? `(${bookingData.imageUrls.length})` : '(Optional)'}
            </Button>

            <Button className="w-full h-12 mt-8" onClick={handleAnalyze} disabled={loading || !bookingData.description}>
              {loading ? 'Analyzing with AI Concierge...' : 'Next: AI Analysis'}
            </Button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-right-4">
            <div className="flex items-center gap-2">
              <Sparkles className="h-5 w-5 text-primary" />
              <h1 className="text-2xl font-bold">AI Concierge Analysis</h1>
            </div>

            {aiAnalysis && (
              <Card className="border-primary/30 bg-card shadow-md shadow-primary/5">
                <CardContent className="p-5 md:p-6 space-y-4">
                  {['EMERGENCY', 'MEDICAL_EMERGENCY'].includes(aiAnalysis.intent) && (
                    <div className="bg-destructive/10 border border-destructive/20 text-destructive rounded-lg p-4">
                      <p className="font-bold text-lg mb-2">Emergency Detected</p>
                      <p>This sounds like an emergency. Co-opConnect's home-service workers are not emergency responders. Please contact the appropriate emergency service.</p>
                    </div>
                  )}

                  {aiAnalysis.intent === 'OUT_OF_SCOPE' && (
                    <div className="bg-amber-500/10 border border-amber-500/20 text-amber-700 dark:text-amber-400 rounded-lg p-4">
                      <p className="font-bold text-lg mb-2">Service Not Available</p>
                      <p>This request isn't a service currently supported by Co-opConnect. We currently support household skilled trades like plumbing, electrical, and AC repair.</p>
                    </div>
                  )}

                  {aiAnalysis.intent === 'CLARIFICATION_REQUIRED' && (
                    <div className="bg-primary/10 border border-primary/20 text-primary-foreground rounded-lg p-4">
                      <p className="font-bold text-lg mb-2 text-primary">Clarification Required</p>
                      <p className="text-foreground mb-4">We are not quite sure what specific service you need. Could you please answer the following to help us:</p>
                      <ul className="list-disc pl-5 text-foreground space-y-1">
                        {aiAnalysis.clarificationQuestions?.map((q: string, i: number) => (
                          <li key={i}>{q}</li>
                        ))}
                      </ul>
                      <Button className="mt-4" onClick={prevStep} variant="outline">Modify Request</Button>
                    </div>
                  )}

                  {aiAnalysis.intent === 'SERVICE_REQUEST' && aiAnalysis.categoryId && (
                    <>
                      <p className="text-muted-foreground mb-4">Our cooperative AI parsed your requirements:</p>
                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <p className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Category</p>
                          <p className="text-lg font-bold text-primary">{aiAnalysis.category}</p>
                        </div>
                        <div>
                          <p className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Urgency</p>
                          <span className={`inline-block px-2.5 py-0.5 rounded-full text-xs font-bold ${
                            aiAnalysis.urgency === 'URGENT' ? 'bg-amber-500 text-white' : 'bg-emerald-600 text-white'
                          }`}>
                            {aiAnalysis.urgency}
                          </span>
                        </div>
                        <div>
                          <p className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Est. Duration</p>
                          <p className="font-semibold text-foreground">{aiAnalysis.estimatedDuration}</p>
                        </div>
                        <div>
                          <p className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Base Rate</p>
                          <p className="font-semibold text-foreground">₹{bookingData.estimatedPrice}</p>
                        </div>
                      </div>
                      <div>
                        <p className="text-xs text-muted-foreground font-semibold uppercase tracking-wider mb-2">Required Tools for Technician</p>
                        <div className="flex flex-wrap gap-2">
                          {aiAnalysis.toolsNeeded?.map((t: string) => (
                            <span key={t} className="bg-secondary border border-border px-2.5 py-1 rounded-md text-xs font-medium text-foreground">
                              {t}
                            </span>
                          ))}
                        </div>
                      </div>
                    </>
                  )}
                </CardContent>
              </Card>
            )}

            {aiAnalysis?.intent === 'SERVICE_REQUEST' && aiAnalysis?.categoryId && (
              <Button className="w-full h-12 mt-8" onClick={nextStep}>
                Looks Good, Proceed to Location
              </Button>
            )}
            {aiAnalysis?.intent !== 'SERVICE_REQUEST' && (
              <Button variant="outline" className="w-full h-12 mt-8" onClick={prevStep}>
                Go Back
              </Button>
            )}
          </div>
        )}

        {step === 3 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-right-4">
            <h1 className="text-2xl font-bold">Where is the service needed?</h1>
            <p className="text-muted-foreground">Confirm your service address.</p>

            {savedLocations.length > 0 && (
              <div className="mb-4">
                <p className="text-sm font-semibold mb-2">Previous Locations</p>
                <div className="grid gap-2">
                  {savedLocations.map(loc => (
                    <div 
                      key={loc.id} 
                      onClick={() => {
                        setBookingData({ ...bookingData, address: loc.address, latitude: loc.latitude, longitude: loc.longitude });
                      }}
                      className={`p-3 border rounded-lg cursor-pointer transition-colors text-left ${bookingData.address === loc.address ? 'border-primary bg-primary/5' : 'hover:border-primary/50'}`}
                    >
                      <p className="text-sm font-medium">{loc.address}</p>
                      <p className="text-xs text-muted-foreground">{loc.city}, {loc.state}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="relative mt-2">
              <label htmlFor="service-address" className="sr-only">Service Address</label>
              <MapPin className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-muted-foreground" />
              <Input
                id="service-address"
                name="address"
                autoComplete="street-address"
                value={bookingData.address}
                onChange={(e) => setBookingData({ ...bookingData, address: e.target.value })}
                placeholder="Or enter new address (e.g., Flat 402, Vastrapur, Ahmedabad)"
                className="pl-10 h-12 text-base"
              />
            </div>
            
            <Button
              variant="outline"
              className="w-full h-12 gap-2"
              onClick={async () => {
                try {
                  const position = await new Promise<GeolocationPosition>((resolve, reject) => {
                    navigator.geolocation.getCurrentPosition(resolve, reject);
                  });
                  const lat = position.coords.latitude;
                  const lng = position.coords.longitude;
                  
                  const res = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json`);
                  const data = await res.json();
                  if (data && data.display_name) {
                    setBookingData({ ...bookingData, address: data.display_name, latitude: lat, longitude: lng });
                    toast.success("Location updated!");
                  } else {
                    setBookingData({ ...bookingData, latitude: lat, longitude: lng });
                    toast.error("Got location but couldn't reverse geocode address.");
                  }
                } catch (e) {
                  toast.error("Could not get your location");
                }
              }}
            >
              <MapPin className="h-4 w-4" /> Use My Location
            </Button>

            <Button className="w-full h-12 mt-8" onClick={handleMatchWorkers} disabled={loading || !bookingData.address}>
              {loading ? 'Finding Verified Cooperative Workers...' : 'Find Verified Workers'}
            </Button>
          </div>
        )}

        {step === 4 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-right-4">
            <h1 className="text-2xl font-bold">Top Matched Workers</h1>
            <p className="text-muted-foreground">
              FairMatch composite scoring based on skills, punctuality, distance & fairness.
            </p>

            <div className="flex flex-col gap-4">
              {matchedWorkers.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground flex flex-col items-center gap-4">
                  <p>No available workers found for this criteria.</p>
                  <Button variant="outline" onClick={prevStep}>Change Location or Requirements</Button>
                </div>
              ) : (
                matchedWorkers.map((match) => {
                  const workerObj = match.worker || match;
                  const userObj = workerObj.user || {};
                  const isSelected = bookingData.workerId === workerObj.id;

                  return (
                    <Card
                      key={workerObj.id}
                      className={`cursor-pointer transition-all bg-card ${
                        isSelected ? 'border-primary ring-2 ring-primary/30 bg-primary/10' : 'border-border/80 hover:border-primary/50'
                      }`}
                      onClick={() => {
                        setSelectedWorker(match);
                        setBookingData({
                          ...bookingData,
                          workerId: workerObj.id,
                          estimatedPrice: match.estimatedPrice || bookingData.estimatedPrice,
                        });
                        nextStep();
                      }}
                    >
                      <CardContent className="p-4 flex gap-4 items-center">
                        <div className="w-14 h-14 bg-primary/10 text-primary font-bold rounded-full flex items-center justify-center flex-shrink-0 text-xl">
                          {userObj.name?.[0] || 'W'}
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex justify-between items-start">
                            <div>
                              <h3 className="font-semibold text-base flex items-center gap-1.5">
                                {userObj.name || 'Cooperative Worker'}
                                <ShieldCheck className="h-4 w-4 text-primary" />
                              </h3>
                              <p className="text-xs text-muted-foreground">{workerObj.primaryTrade || 'Technician'} • {workerObj.experience ? `${workerObj.experience} yrs exp` : 'Verified Member'}</p>
                            </div>
                            <span className="font-bold text-primary">₹{match.estimatedPrice || bookingData.estimatedPrice || 450}</span>
                          </div>
                          <div className="flex items-center gap-3 mt-2 text-xs text-muted-foreground">
                            <span>{workerObj.averageRating > 0 ? `⭐ ${workerObj.averageRating.toFixed(1)}` : '⭐ New'}</span>
                            <span>•</span>
                            <span>{match.distanceKm !== undefined ? `${match.distanceKm} km away` : 'Nearby'}</span>
                            <span>•</span>
                            <span>{workerObj.totalJobs || 0} jobs</span>
                          </div>
                          <div className="mt-2">
                            <MatchScore
                              score={match.compositeScore || match.match_score || 90}
                              reasons={[
                                workerObj.punctualityScore ? `Punctuality: ${workerObj.punctualityScore}%` : `Cooperative FairMatch`,
                                `Fair wage certified`,
                              ]}
                            />
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  );
                })
              )}
            </div>
          </div>
        )}

        {step === 5 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-right-4">
            <h1 className="text-2xl font-bold">Schedule Appointment</h1>
            <p className="text-muted-foreground">Choose your preferred date and time slot.</p>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label htmlFor="service-date" className="text-sm font-medium">Date</label>
                <div className="relative">
                  <CalendarIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    id="service-date"
                    name="date"
                    autoComplete="off"
                    type="date"
                    value={bookingData.date}
                    onChange={(e) => setBookingData({ ...bookingData, date: e.target.value })}
                    className="pl-9 h-12"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label htmlFor="service-time" className="text-sm font-medium">Time Slot</label>
                <div className="relative">
                  <Clock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    id="service-time"
                    name="time"
                    autoComplete="off"
                    type="text"
                    value={bookingData.time}
                    onChange={(e) => setBookingData({ ...bookingData, time: e.target.value })}
                    placeholder="e.g. 11:00 AM"
                    className="pl-9 h-12"
                  />
                </div>
              </div>
            </div>

            <Button
              className="w-full h-12 mt-8"
              onClick={nextStep}
              disabled={!bookingData.date || !bookingData.time}
            >
              Continue to Price Breakdown
            </Button>
          </div>
        )}

        {step === 6 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-right-4">
            <h1 className="text-2xl font-bold">Transparent Price Breakdown</h1>
            <PriceEstimate
              basePrice={bookingData.estimatedPrice}
              taxes={Math.round(bookingData.estimatedPrice * 0.05)}
              platformFee={Math.round(bookingData.estimatedPrice * 0.05)}
              total={Math.round(bookingData.estimatedPrice * 1.1)}
            />
            <div className="bg-secondary/50 p-4 rounded-xl text-xs space-y-1.5 text-muted-foreground border border-border/80">
              <p className="font-bold text-foreground">Cooperative Guarantee:</p>
              <p>• 100% transparent fee structure (5% cooperative fund, 2% worker welfare fund, 5% GST).</p>
              <p>• 30-day service warranty activated automatically upon job completion.</p>
              <p>• Secure 4-digit PIN verification before work begins.</p>
            </div>
            <Button className="w-full h-12 mt-8" onClick={nextStep}>
              Review & Confirm
            </Button>
          </div>
        )}

        {step === 7 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-right-4">
            <h1 className="text-2xl font-bold">Review Booking Details</h1>

            <Card className="bg-card border-border/80">
              <CardContent className="p-6 space-y-4">
                <div>
                  <p className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Service Request</p>
                  <p className="font-bold text-base mt-1 text-foreground">{bookingData.categoryName}</p>
                  <p className="text-sm text-muted-foreground">{bookingData.description}</p>
                </div>
                <div className="grid grid-cols-2 gap-4 pt-4 border-t">
                  <div>
                    <p className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Date & Time</p>
                    <p className="font-medium mt-1">{bookingData.date} at {bookingData.time}</p>
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Address</p>
                    <p className="font-medium mt-1">{bookingData.address}</p>
                  </div>
                </div>
                <div className="pt-4 border-t flex justify-between items-center">
                  <div>
                    <p className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Estimated Total</p>
                    <p className="text-2xl font-black text-primary">₹{Math.round(bookingData.estimatedPrice * 1.1)}</p>
                  </div>
                  <div className="text-right text-xs text-muted-foreground">
                    Includes GST & 30-day warranty
                  </div>
                </div>
              </CardContent>
            </Card>

            <Button
              size="lg"
              className="w-full h-14 text-lg mt-8 gap-2 font-bold"
              onClick={handleConfirm}
              disabled={loading}
            >
              {loading ? 'Confirming with Cooperative...' : (
                <>
                  CONFIRM BOOKING <Check className="h-5 w-5" />
                </>
              )}
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}

export default function BookServicePage() {
  return (
    <Suspense fallback={<div className="p-8 text-center text-muted-foreground min-h-[60vh] flex items-center justify-center">Loading booking service...</div>}>
      <BookServiceContent />
    </Suspense>
  );
}

import { auth } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { notFound, redirect } from 'next/navigation';
import { BookingTimeline } from '@/components/shared/booking-timeline';
import { ServicePinDisplay } from '@/components/shared/service-pin-display';
import { ProofGallery } from '@/components/shared/proof-gallery';
import { InvoiceView } from '@/components/shared/invoice-view';
import { PaymentSummary } from '@/components/shared/payment-summary';
import { RatingInput } from '@/components/shared/rating-input';
import { MaterialApproval } from '@/components/shared/material-approval';
import { WorkerCard } from '@/components/shared/worker-card';
import { CustomerBookingActions } from '@/components/customer/customer-booking-actions';
import { RealtimeBookingListener } from '@/components/shared/realtime-listeners';
import { LiveMap } from '@/components/shared/live-map';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Map, ShieldCheck } from 'lucide-react';
import Link from 'next/link';
import { SOSButton } from '@/components/safety/SOSButton';

export default async function BookingDetailPage({ params }: { params: Promise<{ id: string }> | { id: string } }) {
  const session = await auth();
  
  if (!session || !session.user) {
    redirect('/login');
  }

  const resolvedParams = await params;
  const bookingId = resolvedParams.id;

  const booking = await prisma.booking.findUnique({
    where: { id: bookingId },
    include: {
      category: true,
      worker: {
        include: {
          user: true,
          cooperative: true,
        },
      },
      materialRequests: true,
      invoice: {
        include: {
          items: true,
        },
      },
      jobProofs: true,
      rating: true,
      payment: true,
      warranty: true,
      statusHistory: {
        orderBy: { createdAt: 'asc' },
      },
    },
  });

  if (!booking) notFound();

  const isCompleted = booking.status === 'COMPLETED';
  const showPin = ['ACCEPTED', 'TRAVELLING', 'ARRIVED'].includes(booking.status);
  const isTravelling = booking.status === 'TRAVELLING';
  const isCancellable = !isCompleted && booking.status !== 'CANCELLED';

  return (
    <div className="flex flex-col gap-6 p-4 pb-20 md:p-8 max-w-3xl mx-auto w-full">
      <RealtimeBookingListener userId={session.user?.id as string} role="customer" />
      
      <header className="flex justify-between items-start">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold tracking-tight">Booking #{booking.id.slice(0, 8)}</h1>
            <span className="px-2.5 py-0.5 rounded-full text-xs font-bold bg-primary/10 text-primary">
              {booking.status}
            </span>
          </div>
          <p className="text-sm text-muted-foreground mt-1">{booking.category.name} • {booking.address || 'Ahmedabad'}</p>
        </div>
        <div className="flex gap-2">
          {isCancellable && (
            <SOSButton bookingId={booking.id} />
          )}
          {isCompleted && (
            <Link href={`/customer/book?query=${encodeURIComponent(booking.category.name)}`}>
              <Button variant="outline" size="sm">Book Again</Button>
            </Link>
          )}
        </div>
      </header>

      {/* Booking status timeline */}
      <section className="bg-card p-5 rounded-xl border shadow-xs">
        <h3 className="font-bold text-sm text-foreground mb-4">Job Status History</h3>
        <BookingTimeline statusHistory={booking.statusHistory} />
      </section>

      {showPin && (
        <section className="bg-card p-5 rounded-xl border shadow-xs text-center">
          <ServicePinDisplay pin={booking.servicePin || '4827'} />
          <p className="text-xs text-muted-foreground mt-2">
            Share this 4-digit security PIN with the worker when they arrive at your location to begin work.
          </p>
        </section>
      )}

      {isTravelling && booking.worker && (
        <Card className="border-primary/50 bg-primary/5">
          <CardContent className="p-4 flex flex-col gap-3">
            <div className="flex justify-between items-center">
              <h3 className="font-semibold text-sm flex items-center gap-2 text-primary">
                <Map className="h-4 w-4" /> Live Worker Tracking
              </h3>
            </div>
            <LiveMap 
              height="200px"
              center={
                booking.worker.latitude && booking.worker.longitude
                  ? [booking.worker.latitude, booking.worker.longitude]
                  : booking.latitude && booking.longitude 
                    ? [booking.latitude, booking.longitude]
                    : undefined
              }
              markers={[
                ...(booking.latitude && booking.longitude ? [{
                  lat: booking.latitude,
                  lng: booking.longitude,
                  label: "Service Location",
                }] : []),
                ...(booking.worker.latitude && booking.worker.longitude ? [{
                  lat: booking.worker.latitude,
                  lng: booking.worker.longitude,
                  label: `${booking.worker.user.name || 'Worker'} (En Route)`,
                  isWorker: true,
                }] : [])
              ]}
            />
          </CardContent>
        </Card>
      )}

      {booking.worker && (
        <section className="space-y-3">
          <h2 className="text-base font-bold text-foreground">Assigned Worker</h2>
          <WorkerCard worker={booking.worker} href={`/customer/workers/${booking.worker.id}`} />
        </section>
      )}

      {booking.materialRequests && booking.materialRequests.length > 0 && (
        <section className="space-y-3">
          <h2 className="text-base font-bold text-foreground">Additional Material Approvals</h2>
          <div className="flex flex-col gap-3">
            {booking.materialRequests.map((mat: any) => (
              <MaterialApproval key={mat.id} material={mat} bookingId={booking.id} />
            ))}
          </div>
        </section>
      )}

      {booking.jobProofs && booking.jobProofs.length > 0 && (
        <section className="space-y-3">
          <h2 className="text-base font-bold text-foreground">Before & After Job Proof</h2>
          <ProofGallery proofs={booking.jobProofs} />
        </section>
      )}

      {isCompleted && booking.invoice && (
        <section className="space-y-3">
          <h2 className="text-base font-bold text-foreground">Digital Tax Invoice</h2>
          <InvoiceView invoice={booking.invoice} />
          {booking.payment && <PaymentSummary payment={booking.payment} />}
        </section>
      )}

      {isCompleted && booking.warranty && (
        <Card className="border-green-500/30 bg-green-500/5 p-4">
          <CardContent className="p-0 flex items-center gap-3">
            <ShieldCheck className="h-6 w-6 text-green-600 shrink-0" />
            <div>
              <p className="font-bold text-sm text-green-800">Cooperative Service Warranty Active</p>
              <p className="text-xs text-green-700">
                Valid until {new Date(booking.warranty.expiryDate).toLocaleDateString()}. Free rework covered by cooperative quality guarantee.
              </p>
            </div>
          </CardContent>
        </Card>
      )}

      {isCompleted && !booking.rating && (
        <section className="space-y-3 mt-2">
          <RatingInput bookingId={booking.id} />
        </section>
      )}

      <CustomerBookingActions
        bookingId={booking.id}
        invoice={booking.invoice}
        payment={booking.payment}
        status={booking.status}
      />
    </div>
  );
}

import { auth } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { redirect } from 'next/navigation';
import { BookingCard } from '@/components/shared/booking-card';
import { EmptyState } from '@/components/shared/empty-state';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';

export default async function BookingsPage() {
  const session = await auth();
  
  if (!session || !session.user) {
    redirect('/login');
  }

  const customerId = session.user.customerId;

  const allBookings = customerId
    ? await prisma.booking.findMany({
        where: { customerId },
        include: {
          category: true,
          worker: {
            include: {
              user: true,
            },
          },
        },
        orderBy: { createdAt: 'desc' },
      })
    : [];

  const active = allBookings.filter(b => ['REQUESTED', 'ACCEPTED', 'TRAVELLING', 'ARRIVED', 'IN_PROGRESS'].includes(b.status));
  const upcoming = allBookings.filter(b => ['REQUESTED', 'ACCEPTED'].includes(b.status));
  const completed = allBookings.filter(b => b.status === 'COMPLETED');

  const renderList = (list: any[]) => {
    if (list.length === 0) return <EmptyState title="No bookings found" description="You don't have any bookings in this category." />;
    return (
      <div className="flex flex-col gap-4 mt-4">
        {list.map(booking => (
          <BookingCard key={booking.id} booking={booking} href={`/customer/bookings/${booking.id}`} />
        ))}
      </div>
    );
  };

  return (
    <div className="flex flex-col gap-6 p-4 pb-20 md:p-8 max-w-7xl mx-auto w-full">
      <header>
        <h1 className="text-2xl font-bold tracking-tight mb-2">My Bookings</h1>
        <p className="text-muted-foreground">Manage your service requests and history.</p>
      </header>

      <Tabs defaultValue="active" className="w-full">
        <TabsList className="w-full grid grid-cols-4 h-auto p-1">
          <TabsTrigger value="active" className="py-2 text-xs sm:text-sm">Active</TabsTrigger>
          <TabsTrigger value="upcoming" className="py-2 text-xs sm:text-sm">Upcoming</TabsTrigger>
          <TabsTrigger value="completed" className="py-2 text-xs sm:text-sm">Past</TabsTrigger>
          <TabsTrigger value="all" className="py-2 text-xs sm:text-sm">All</TabsTrigger>
        </TabsList>
        <TabsContent value="active">{renderList(active)}</TabsContent>
        <TabsContent value="upcoming">{renderList(upcoming)}</TabsContent>
        <TabsContent value="completed">{renderList(completed)}</TabsContent>
        <TabsContent value="all">{renderList(allBookings)}</TabsContent>
      </Tabs>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { AlertTriangle, MapPin, Zap, Droplets, Wrench } from 'lucide-react';
import { toast } from 'sonner';

const emergencyCategories = [
  { id: 'electrical', name: 'Electrical Emergency', icon: Zap, color: 'text-yellow-500', bg: 'bg-yellow-500/10' },
  { id: 'water', name: 'Water Leakage', icon: Droplets, color: 'text-blue-500', bg: 'bg-blue-500/10' },
  { id: 'plumbing', name: 'Plumbing Emergency', icon: Wrench, color: 'text-orange-500', bg: 'bg-orange-500/10' },
];

export default function EmergencyBookingPage() {
  const router = useRouter();
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [address, setAddress] = useState('');
  const [loading, setLoading] = useState(false);

  const handleBookEmergency = async () => {
    if (!selectedCategory || !address) {
      toast.error('Please select a category and provide an address.');
      return;
    }
    
    setLoading(true);
    try {
      const res = await fetch('/api/bookings/emergency', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ category: selectedCategory, address })
      });
      
      if (!res.ok) throw new Error('Failed to book emergency service');
      const data = await res.json();
      
      router.push(`/customer/bookings/${data.id}`);
    } catch (error) {
      toast.error('Something went wrong. Please try again.');
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col gap-6 p-4 md:p-8 max-w-xl mx-auto w-full">
      <header className="text-center flex flex-col items-center">
        <div className="w-16 h-16 bg-destructive/10 rounded-full flex items-center justify-center mb-4 text-destructive">
          <AlertTriangle className="h-8 w-8" />
        </div>
        <h1 className="text-2xl font-bold tracking-tight text-destructive mb-2">Emergency Service</h1>
        <p className="text-muted-foreground">We'll dispatch the nearest available qualified worker immediately.</p>
      </header>

      <div className="space-y-4 mt-4">
        <Label className="text-base">1. What's the emergency?</Label>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          {emergencyCategories.map(cat => {
            const Icon = cat.icon;
            const isSelected = selectedCategory === cat.id;
            return (
              <Card 
                key={cat.id}
                className={`cursor-pointer transition-all border-2 ${isSelected ? 'border-destructive bg-destructive/5' : 'border-border hover:border-destructive/50'}`}
                onClick={() => setSelectedCategory(cat.id)}
              >
                <CardContent className="flex flex-col items-center justify-center p-4 gap-2 text-center h-full">
                  <div className={`p-3 rounded-full ${cat.bg} ${cat.color}`}>
                    <Icon className="h-6 w-6" />
                  </div>
                  <span className="font-medium text-sm">{cat.name}</span>
                </CardContent>
              </Card>
            );
          })}
        </div>
      </div>

      <div className="space-y-4">
        <Label className="text-base">2. Where do you need help?</Label>
        <div className="relative">
          <MapPin className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-muted-foreground" />
          <Input 
            value={address}
            onChange={e => setAddress(e.target.value)}
            placeholder="Enter your full address" 
            className="pl-10 h-12"
          />
        </div>
      </div>

      <Button 
        size="lg" 
        variant="destructive" 
        className="w-full h-14 text-lg font-bold mt-4"
        onClick={handleBookEmergency}
        disabled={loading || !selectedCategory || !address}
      >
        {loading ? 'FINDING WORKER...' : 'REQUEST EMERGENCY HELP'}
      </Button>
    </div>
  );
}

import { auth } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { redirect } from 'next/navigation';
import Link from 'next/link';
import { Button } from '@/components/ui/button';
import { AIConciergeSearch } from '@/components/customer/ai-concierge-search';
import { ServiceCard } from '@/components/shared/service-card';
import { BookingCard } from '@/components/shared/booking-card';
import { WorkerCard } from '@/components/shared/worker-card';
import { EmptyState } from '@/components/shared/empty-state';
import { AlertTriangle, Sparkles } from 'lucide-react';
import { ScrollArea, ScrollBar } from '@/components/ui/scroll-area';

export default async function CustomerHomePage() {
  const session = await auth();
  
  if (!session || !session.user) {
    redirect('/login');
  }

  const customerId = session.user.customerId;

  const [activeBookings, popularServices, nearbyWorkers, recentBookings, latestLocation] = await Promise.all([
    customerId
      ? prisma.booking.findMany({
          where: {
            customerId,
            status: { in: ['REQUESTED', 'ACCEPTED', 'TRAVELLING', 'ARRIVED', 'IN_PROGRESS'] },
          },
          include: {
            category: true,
            worker: { include: { user: true } },
          },
          orderBy: { createdAt: 'desc' },
          take: 3,
        })
      : [],
    prisma.serviceCategory.findMany({
      where: { isActive: true, isEmergency: false },
      take: 6,
      orderBy: { sortOrder: 'asc' },
    }),
    prisma.worker.findMany({
      where: { verificationStatus: 'VERIFIED' },
      include: {
        user: true,
        cooperative: true,
      },
      take: 6,
      orderBy: { averageRating: 'desc' },
    }),
    customerId
      ? prisma.booking.findMany({
          where: {
            customerId,
            status: 'COMPLETED',
          },
          include: {
            category: true,
            worker: { include: { user: true } },
          },
          orderBy: { completedAt: 'desc' },
          take: 3,
        })
      : [],
    customerId 
      ? prisma.customerLocation.findFirst({
          where: { customerId },
          orderBy: { createdAt: 'desc' }
        })
      : null,
  ]);

  const workersAvailableCount = await prisma.worker.count({
    where: {
      verificationStatus: 'VERIFIED',
      availabilityStatus: 'AVAILABLE',
      ...(latestLocation?.city ? { city: latestLocation.city } : {})
    }
  });

  return (
    <div className="flex flex-col gap-6 p-4 md:p-6 lg:p-8 max-w-6xl mx-auto w-full">
      {/* Personalized Greeting Header */}
      <header className="flex justify-between items-center">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-xl md:text-2xl font-black tracking-tight text-foreground">
              Hello, {session.user.name || 'Cooperator'}! 👋
            </h1>
          </div>
          <p className="text-muted-foreground text-xs md:text-sm mt-0.5">
            Verified cooperative services & fair-wage technicians in your area.
          </p>
          <div className="mt-3">
            <span className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-emerald-500/10 text-emerald-600 font-semibold text-xs md:text-sm border border-emerald-500/20">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
              {latestLocation?.city ? `Workers Available Near You (${latestLocation.city}): ${workersAvailableCount}` : `Workers Available Globally: ${workersAvailableCount}`}
            </span>
            {!latestLocation?.city && (
              <p className="text-[10px] text-muted-foreground mt-1 ml-1">Please set your location during booking to see nearby workers.</p>
            )}
          </div>
        </div>
        <Link href="/customer/profile" className="shrink-0">
          <div className="w-10 h-10 rounded-xl bg-primary/15 border border-primary/30 flex items-center justify-center text-primary font-bold text-base transition-colors">
            {session.user.name?.charAt(0) || 'U'}
          </div>
        </Link>
      </header>

      {/* AI Concierge Hero Card */}
      <section className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-card via-card to-primary/5 border border-primary/25 p-4 md:p-5 shadow-lg shadow-primary/5">
        <div className="flex items-center justify-between gap-2 mb-2.5">
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 rounded-lg bg-primary/20 flex items-center justify-center text-primary">
              <Sparkles className="w-4 h-4" />
            </div>
            <h2 className="font-bold text-sm md:text-base text-foreground">Cooperative AI Concierge</h2>
          </div>
          <span className="text-[10px] font-bold uppercase tracking-wider bg-primary/15 text-primary border border-primary/30 px-2 py-0.5 rounded-full">
            Gemini Powered
          </span>
        </div>
        <p className="text-xs text-muted-foreground mb-3">
          Describe any household or maintenance problem by text or voice in English, Hindi, or Gujarati.
        </p>
        <AIConciergeSearch />
      </section>

      {/* Emergency Quick Action */}
      <section>
        <Link href="/customer/emergency" className="block group">
          <div className="flex items-center justify-between p-3.5 rounded-xl bg-destructive/10 border border-destructive/30 hover:border-destructive/60 hover:bg-destructive/15 transition-all">
            <div className="flex items-center gap-3">
              <div className="w-9 h-9 rounded-lg bg-destructive flex items-center justify-center text-white shrink-0 group- transition-colors">
                <AlertTriangle className="h-5 w-5" />
              </div>
              <div>
                <p className="font-bold text-sm text-foreground">Need Urgent Emergency Help?</p>
                <p className="text-xs text-muted-foreground">Rapid-dispatch electricians, plumbers, and emergency repair</p>
              </div>
            </div>
            <span className="hidden sm:inline-flex text-xs font-bold text-destructive  transition-colors">
              Request Emergency &rarr;
            </span>
          </div>
        </Link>
      </section>

      {/* Active Bookings (if any) */}
      {activeBookings.length > 0 && (
        <section className="space-y-3">
          <div className="flex items-center justify-between">
            <h2 className="text-base font-bold text-foreground flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-primary animate-pulse" />
              Active Bookings
            </h2>
            <Link href="/customer/bookings" className="text-xs text-primary font-semibold hover:underline">
              View All
            </Link>
          </div>
          <div className="flex flex-col gap-3">
            {activeBookings.map((booking) => (
              <BookingCard key={booking.id} booking={booking} />
            ))}
          </div>
        </section>
      )}

      {/* Popular Services */}
      <section className="space-y-3">
        <div className="flex justify-between items-center">
          <h2 className="text-base font-bold text-foreground">Popular Cooperative Services</h2>
          <Link href="/customer/services" className="text-xs text-primary font-semibold hover:underline">
            View All Services &rarr;
          </Link>
        </div>
        {popularServices.length > 0 ? (
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-3 gap-3 md:gap-4">
            {popularServices.map((service) => (
              <ServiceCard key={service.id} service={service} />
            ))}
          </div>
        ) : (
          <EmptyState title="No services found" description="Check back later." />
        )}
      </section>

      {/* Nearby Verified Workers */}
      <section className="space-y-3">
        <div className="flex justify-between items-center">
          <h2 className="text-base font-bold text-foreground">Nearby Verified Workers</h2>
          <Link href="/customer/services" className="text-xs text-primary font-semibold hover:underline">
            Browse All &rarr;
          </Link>
        </div>
        {nearbyWorkers.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {nearbyWorkers.map((worker) => (
              <WorkerCard key={worker.id} worker={worker} />
            ))}
          </div>
        ) : (
          <EmptyState title="No nearby workers" description="We couldn't find any verified workers in your area." />
        )}
      </section>

      {/* Recent Services */}
      {recentBookings.length > 0 && (
        <section className="space-y-3">
          <h2 className="text-base font-bold text-foreground">Recent Services</h2>
          <div className="flex flex-col gap-3">
            {recentBookings.map((booking) => (
              <BookingCard key={booking.id} booking={booking} />
            ))}
          </div>
        </section>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { Button } from '@/components/ui/button';
import { NotificationItem } from '@/components/shared/notification-item';
import { EmptyState } from '@/components/shared/empty-state';
import { CheckCheck } from 'lucide-react';
import { Skeleton } from '@/components/ui/skeleton';

export default function NotificationsPage() {
  const [notifications, setNotifications] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const channelRef = useRef<any>(null);

  useEffect(() => {
    let cancelled = false;

    async function init() {
      try {
        const [sessionRes, notifRes] = await Promise.all([
          fetch('/api/auth/session'),
          fetch('/api/notifications'),
        ]);
        const sessionData = await sessionRes.json();
        const data = await notifRes.json();

        if (cancelled) return;
        setNotifications(data.notifications || []);

        const userId = sessionData?.user?.id;
        if (userId) {
          const { supabase } = await import('@/lib/supabase');
          if (cancelled) return;

          const ch = supabase
            .channel(`customer-notifications-${userId}`)
            .on(
              'postgres_changes',
              { event: 'INSERT', schema: 'public', table: 'Notification', filter: `userId=eq.${userId}` },
              () => {
                fetch('/api/notifications')
                  .then(r => r.json())
                  .then(d => {
                    if (!cancelled) setNotifications(d.notifications || []);
                  });
              }
            )
            .subscribe();

          channelRef.current = ch;
        }
      } catch (err) {
        console.error(err);
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    init();

    return () => {
      cancelled = true;
      if (channelRef.current) {
        import('@/lib/supabase').then(({ supabase }) => {
          supabase.removeChannel(channelRef.current);
          channelRef.current = null;
        });
      }
    };
  }, []);

  const markAllAsRead = async () => {
    try {
      await fetch('/api/notifications', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ markAll: true }),
      });
      setNotifications(notifications.map(n => ({ ...n, isRead: true })));
    } catch (err) {
      console.error(err);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col gap-6 p-4 pb-20 md:p-8 max-w-2xl mx-auto w-full">
        <header className="flex items-center justify-between">
          <div>
            <Skeleton className="h-8 w-48 mb-2" />
            <Skeleton className="h-4 w-64" />
          </div>
        </header>
        <div className="flex flex-col gap-2 mt-2">
          {[1, 2, 3, 4].map(i => (
            <div key={i} className="flex gap-4 p-4 border-b">
              <Skeleton className="h-10 w-10 rounded-full shrink-0" />
              <div className="flex-1 space-y-2">
                <div className="flex justify-between">
                  <Skeleton className="h-4 w-1/3" />
                  <Skeleton className="h-3 w-16" />
                </div>
                <Skeleton className="h-3 w-full" />
                <Skeleton className="h-3 w-4/5" />
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 p-4 pb-20 md:p-8 max-w-2xl mx-auto w-full">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight mb-1">Notifications</h1>
          <p className="text-muted-foreground text-sm">Stay updated on your bookings.</p>
        </div>
        {notifications.length > 0 && (
          <Button variant="ghost" size="sm" onClick={markAllAsRead} className="gap-2">
            <CheckCheck className="h-4 w-4" />
            Mark all read
          </Button>
        )}
      </header>

      {notifications.length === 0 ? (
        <EmptyState title="No notifications" description="You're all caught up!" />
      ) : (
        <div className="flex flex-col gap-2">
          {notifications.map(notification => (
            <NotificationItem key={notification.id} notification={notification} />
          ))}
        </div>
      )}
    </div>
  );
}

import { auth } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { notFound, redirect } from 'next/navigation';
import { getWorkerProfile } from '@/services/worker-profile';
import { TrustPassport } from '@/components/shared/trust-passport';
import { TrustedWorkerButton } from '@/components/customer/trusted-worker-button';
import { Button } from '@/components/ui/button';
import Link from 'next/link';

export default async function CustomerWorkerProfilePage({
  params,
}: {
  params: Promise<{ id: string }> | { id: string };
}) {
  const session = await auth();

  if (!session || !session.user) {
    redirect('/login');
  }

  const resolvedParams = await params;
  const workerId = resolvedParams.id;
  const customerId = session.user.customerId;

  const profileData = await getWorkerProfile(workerId);

  if (!profileData) notFound();

  const { worker } = profileData;

  // Check if trusted
  let isTrusted = false;
  if (customerId) {
    const trusted = await prisma.trustedWorker.findUnique({
      where: {
        customerId_workerId: {
          customerId,
          workerId
        }
      }
    });
    isTrusted = !!trusted;
  }

  return (
    <div className="flex flex-col gap-6 p-4 pb-20 md:p-8 max-w-3xl mx-auto w-full">
      <header className="flex justify-between items-start mb-2">
        <div>
          <h1 className="text-2xl font-bold tracking-tight mb-1">{worker.user?.name}'s Profile</h1>
          <p className="text-muted-foreground">
            {worker.primaryTrade || 'Technician'} • Member of {worker.cooperative?.name || 'Cooperative'}
          </p>
        </div>
        <div className="flex gap-2">
          <TrustedWorkerButton workerId={worker.id} initialIsTrusted={isTrusted} />
          <Link href={`/customer/book?workerId=${worker.id}`}>
            <Button>Book Worker</Button>
          </Link>
        </div>
      </header>

      <TrustPassport profileData={profileData} />

      <div className="flex flex-col sm:hidden gap-3 mt-4">
        <Link href={`/customer/book?workerId=${worker.id}`} className="w-full">
          <Button className="w-full">Book Worker</Button>
        </Link>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { ArrowLeft, Mail, Loader2, CheckCircle2, Shield } from 'lucide-react';

export default function ForgotPasswordPage() {
  const [email, setEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isLoading) return; // Prevent duplicate submissions
    setError('');
    
    if (!email.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setError('Please enter a valid email address.');
      return;
    }

    setIsLoading(true);

    try {
      const res = await fetch('/api/auth/forgot-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }),
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || 'Failed to request password reset');
      }

      setIsSuccess(true);
    } catch (err) {
      setError((err instanceof Error ? err.message : "Unknown error") || 'An unexpected error occurred. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex">
      {/* Left panel - decorative */}
      <div className="hidden lg:flex lg:w-1/2 bg-gradient-to-br from-card via-[#0b1329] to-[#091638] border-r border-border/80 relative overflow-hidden">
        <div className="absolute inset-0 bg-radial from-primary/10 via-transparent to-transparent" />
        <div className="relative z-10 flex flex-col justify-center px-16">
          <div className="flex items-center gap-3 mb-8">
            <div className="w-12 h-12 bg-primary/20 border border-primary/30 rounded-2xl flex items-center justify-center">
              <Shield className="w-7 h-7 text-primary" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-foreground">Co-opConnect</h1>
              <p className="text-sm text-primary">Cooperative Services Platform</p>
            </div>
          </div>
          <h2 className="text-4xl font-black text-foreground leading-tight mb-4 tracking-tight">
            Forgot your password?
            <br />
            No problem.
          </h2>
          <p className="text-muted-foreground text-base max-w-md">
            Enter your registered email address and we'll send you instructions to securely reset your password.
          </p>
        </div>
      </div>

      {/* Right panel - form */}
      <div className="flex-1 flex items-center justify-center p-6 bg-background">
        <div className="w-full max-w-md">
          {/* Mobile logo */}
          <div className="lg:hidden flex items-center gap-2 mb-8">
            <div className="w-10 h-10 bg-primary/20 border border-primary/30 rounded-xl flex items-center justify-center shadow-md shadow-primary/20">
              <Shield className="w-5 h-5 text-primary" />
            </div>
            <span className="font-bold text-xl text-foreground">Co-opConnect</span>
          </div>

          <h2 className="text-2xl font-black text-foreground mb-1 tracking-tight">Reset Password</h2>
          
          {isSuccess ? (
            <div className="mt-8 text-center bg-secondary/50 p-8 rounded-2xl border border-border/80 shadow-sm">
              <CheckCircle2 className="mx-auto h-12 w-12 text-emerald-500 mb-4" />
              <h3 className="text-lg font-bold text-foreground mb-2">Check your email</h3>
              <p className="text-sm text-muted-foreground mb-6">
                If an account exists for <span className="font-semibold text-foreground">{email}</span>, we have sent password reset instructions.
              </p>
              <Link
                href="/login"
                className="w-full py-3 bg-primary text-white text-sm font-bold rounded-xl hover:bg-primary/90 transition-all shadow-md shadow-primary/20 flex items-center justify-center"
              >
                Back to Login
              </Link>
            </div>
          ) : (
            <>
              <p className="text-muted-foreground mb-8 text-sm">Enter the email associated with your account.</p>

              {error && (
                <div className="mb-6 p-3 bg-destructive/10 border border-destructive/30 rounded-xl text-xs text-destructive font-medium">
                  {error}
                </div>
              )}

              <form className="space-y-5" onSubmit={handleSubmit}>
                <div>
                  <label htmlFor="email" className="block text-xs font-semibold text-foreground mb-1.5">
                    Email Address
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none">
                      <Mail className="h-4 w-4 text-muted-foreground" />
                    </div>
                    <input
                      id="email"
                      name="email"
                      type="email"
                      autoComplete="email"
                      required
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      className="block w-full pl-10 pr-3.5 py-2.5 border border-border/80 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition-colors bg-secondary/50 text-foreground placeholder:text-muted-foreground"
                      placeholder="name@example.com"
                      disabled={isLoading}
                    />
                  </div>
                </div>

                <button
                  type="submit"
                  disabled={isLoading}
                  className="w-full py-3 bg-primary text-white text-sm font-bold rounded-xl hover:bg-primary/90 transition-all shadow-md shadow-primary/20 disabled:opacity-50 flex items-center justify-center gap-2 cursor-pointer"
                >
                  {isLoading ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin" />
                      Sending Instructions...
                    </>
                  ) : (
                    'Send Reset Link'
                  )}
                </button>
                
                <div className="mt-6 text-center">
                  <Link href="/login" className="inline-flex items-center text-xs text-muted-foreground hover:text-foreground transition-colors font-medium">
                    <ArrowLeft className="w-4 h-4 mr-1.5" />
                    Back to login
                  </Link>
                </div>
              </form>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

