"use client";

import React, { useState } from "react";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Search, ChevronDown, ChevronUp, ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";

export interface Column<T> {
  header: string;
  accessorKey: keyof T | string;
  cell?: (item: T) => React.ReactNode;
  sortable?: boolean;
}

interface DataTableProps<T> {
  columns: Column<T>[];
  data: T[];
  searchable?: boolean;
  searchKey?: keyof T;
  filterable?: boolean;
  pageSize?: number;
  className?: string;
}

export function DataTable<T>({ 
  columns, 
  data, 
  searchable = false, 
  searchKey,
  pageSize = 10,
  className 
}: DataTableProps<T>) {
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [sortConfig, setSortConfig] = useState<{ key: string, direction: "asc" | "desc" } | null>(null);

  // Helper to get nested value
  const getValue = (obj: any, path: string) => {
    return path.split('.').reduce((acc, part) => acc && acc[part], obj);
  };

  // Filter
  const filteredData = React.useMemo(() => {
    if (!searchable || !searchTerm || !searchKey) return data;
    return data.filter(item => {
      const val = getValue(item, String(searchKey));
      if (typeof val === 'string' || typeof val === 'number') {
        return String(val).toLowerCase().includes(searchTerm.toLowerCase());
      }
      return false;
    });
  }, [data, searchable, searchTerm, searchKey]);

  // Sort
  const sortedData = React.useMemo(() => {
    if (!sortConfig) return filteredData;
    
    return [...filteredData].sort((a, b) => {
      const aVal = getValue(a, sortConfig.key);
      const bVal = getValue(b, sortConfig.key);
      
      if (aVal < bVal) return sortConfig.direction === "asc" ? -1 : 1;
      if (aVal > bVal) return sortConfig.direction === "asc" ? 1 : -1;
      return 0;
    });
  }, [filteredData, sortConfig]);

  // Pagination
  const totalPages = Math.ceil(sortedData.length / pageSize);
  const paginatedData = sortedData.slice(
    (currentPage - 1) * pageSize,
    currentPage * pageSize
  );

  const handleSort = (key: string) => {
    let direction: "asc" | "desc" = "asc";
    if (sortConfig && sortConfig.key === key && sortConfig.direction === "asc") {
      direction = "desc";
    }
    setSortConfig({ key, direction });
  };

  return (
    <div className={cn("space-y-4", className)}>
      {searchable && searchKey && (
        <div className="flex items-center gap-2 max-w-sm">
          <Search className="h-4 w-4 text-muted-foreground absolute ml-3" />
          <Input 
            placeholder="Search..." 
            value={searchTerm}
            onChange={(e) => {
              setSearchTerm(e.target.value);
              setCurrentPage(1);
            }}
            className="pl-9"
          />
        </div>
      )}

      <div className="rounded-xl border border-border/80 bg-card overflow-x-auto shadow-xs">
        <Table>
          <TableHeader>
            <TableRow>
              {columns.map((col, idx) => (
                <TableHead 
                  key={idx} 
                  className={cn(col.sortable && "cursor-pointer select-none hover:bg-muted/50")}
                  onClick={() => col.sortable && handleSort(String(col.accessorKey))}
                >
                  <div className="flex items-center gap-1">
                    {col.header}
                    {col.sortable && sortConfig?.key === String(col.accessorKey) && (
                      sortConfig.direction === "asc" ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />
                    )}
                  </div>
                </TableHead>
              ))}
            </TableRow>
          </TableHeader>
          <TableBody>
            {paginatedData.length > 0 ? (
              paginatedData.map((item, rowIndex) => (
                <TableRow key={rowIndex}>
                  {columns.map((col, colIndex) => (
                    <TableCell key={colIndex}>
                      {col.cell 
                        ? col.cell(item) 
                        : (getValue(item, String(col.accessorKey)) as React.ReactNode)}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length} className="h-24 text-center text-muted-foreground">
                  No results.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      {totalPages > 1 && (
        <div className="flex items-center justify-end space-x-2">
          <p className="text-sm text-muted-foreground mr-4">
            Page {currentPage} of {totalPages}
          </p>
          <Button
            variant="outline"
            size="sm"
            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
            disabled={currentPage === 1}
          >
            <ChevronLeft className="h-4 w-4" />
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
          >
            <ChevronRight className="h-4 w-4" />
          </Button>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import dynamic from "next/dynamic";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { cn } from "@/lib/utils";

// Dynamically import map components to avoid SSR issues with Leaflet
const MapContainer = dynamic(
  () => import("react-leaflet").then((mod) => mod.MapContainer),
  { ssr: false, loading: () => <Skeleton className="h-[400px] w-full" /> }
);
const TileLayer = dynamic(
  () => import("react-leaflet").then((mod) => mod.TileLayer),
  { ssr: false }
);
const CircleMarker = dynamic(
  () => import("react-leaflet").then((mod) => mod.CircleMarker),
  { ssr: false }
);
const Popup = dynamic(
  () => import("react-leaflet").then((mod) => mod.Popup),
  { ssr: false }
);

import "leaflet/dist/leaflet.css";

interface LocationData {
  area: string;
  lat: number;
  lng: number;
  count: number;
}

interface DemandMapProps {
  demandData: LocationData[];
  supplyData?: LocationData[];
  title?: string;
  className?: string;
}

export function DemandMap({ demandData, supplyData, title = "Demand Heatmap", className }: DemandMapProps) {
  const [isMounted, setIsMounted] = useState(false);
  const ahmadabadCenter: [number, number] = [23.0225, 72.5714];

  useEffect(() => {
    setIsMounted(true);

    // Fix Leaflet icon issue in Next.js
    if (typeof window !== "undefined") {
      const L = require("leaflet");
      delete L.Icon.Default.prototype._getIconUrl;
      L.Icon.Default.mergeOptions({
        iconRetinaUrl: require("leaflet/dist/images/marker-icon-2x.png").default?.src || "/marker-icon-2x.png",
        iconUrl: require("leaflet/dist/images/marker-icon.png").default?.src || "/marker-icon.png",
        shadowUrl: require("leaflet/dist/images/marker-shadow.png").default?.src || "/marker-shadow.png",
      });
    }
  }, []);

  if (!isMounted) return <Skeleton className={cn("h-[400px] w-full", className)} />;

  return (
    <Card className={cn("overflow-hidden flex flex-col", className)}>
      <CardHeader className="p-4 pb-2 z-10 bg-background relative shadow-sm">
        <CardTitle className="text-base">{title}</CardTitle>
        <div className="flex gap-4 text-xs mt-2">
          <div className="flex items-center gap-1">
            <span className="w-3 h-3 rounded-full bg-red-500 opacity-60"></span> Demand
          </div>
          {supplyData && (
            <div className="flex items-center gap-1">
              <span className="w-3 h-3 rounded-full bg-blue-500 opacity-60"></span> Supply
            </div>
          )}
        </div>
      </CardHeader>
      <CardContent className="p-0 flex-1 relative min-h-[400px]">
        <MapContainer 
          center={ahmadabadCenter} 
          zoom={12} 
          style={{ height: "100%", width: "100%", position: "absolute", inset: 0 }}
          zoomControl={false}
        >
          <TileLayer
            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
            className="map-tiles"
          />

          {demandData.map((loc, idx) => (
            <CircleMarker
              key={`demand-${idx}`}
              center={[loc.lat, loc.lng]}
              radius={Math.max(10, Math.min(30, loc.count * 2))}
              fillColor="#ef4444" // red
              fillOpacity={0.5}
              color="#b91c1c"
              weight={1}
            >
              <Popup>
                <div className="text-sm">
                  <strong>{loc.area}</strong><br />
                  Demand: {loc.count} requests
                </div>
              </Popup>
            </CircleMarker>
          ))}

          {supplyData && supplyData.map((loc, idx) => (
            <CircleMarker
              key={`supply-${idx}`}
              center={[loc.lat, loc.lng]}
              radius={Math.max(10, Math.min(30, loc.count * 2))}
              fillColor="#3b82f6" // blue
              fillOpacity={0.5}
              color="#1d4ed8"
              weight={1}
            >
              <Popup>
                <div className="text-sm">
                  <strong>{loc.area}</strong><br />
                  Available Workers: {loc.count}
                </div>
              </Popup>
            </CircleMarker>
          ))}
        </MapContainer>
      </CardContent>
    </Card>
  );
}

"use client";

import React from "react";
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { MessageSquare, AlertOctagon, Scale } from "lucide-react";
import { formatDateTime, getStatusColor, cn } from "@/lib/utils";

interface Dispute {
  id: string;
  bookingId: string;
  status: "OPEN" | "UNDER_REVIEW" | "RESOLVED" | "ESCALATED";
  customerName: string;
  workerName: string;
  createdAt: string | Date;
  customerStatement: string;
  workerResponse?: string;
  resolution?: string;
}

interface DisputeSummaryProps {
  dispute: Dispute;
  onResolve?: (id: string) => void;
  onEscalate?: (id: string) => void;
  className?: string;
}

export function DisputeSummary({ dispute, onResolve, onEscalate, className }: DisputeSummaryProps) {
  return (
    <Card className={cn("border-destructive/30", className)}>
      <CardHeader className="bg-destructive/5 pb-4">
        <div className="flex justify-between items-start">
          <div className="flex items-center gap-2">
            <AlertOctagon className="h-5 w-5 text-destructive" />
            <div>
              <CardTitle className="text-base text-destructive">Dispute #{dispute.id.slice(-6).toUpperCase()}</CardTitle>
              <p className="text-xs text-muted-foreground mt-1">Reported on {formatDateTime(new Date(dispute.createdAt))}</p>
            </div>
          </div>
          <Badge className={getStatusColor(dispute.status)}>
            {dispute.status.replace(/_/g, ' ')}
          </Badge>
        </div>
      </CardHeader>
      
      <CardContent className="pt-4 space-y-4">
        <div className="grid grid-cols-2 text-sm bg-muted/30 p-2 rounded">
          <div>
            <span className="text-muted-foreground text-xs block">Customer</span>
            <span className="font-medium">{dispute.customerName}</span>
          </div>
          <div>
            <span className="text-muted-foreground text-xs block">Worker</span>
            <span className="font-medium">{dispute.workerName}</span>
          </div>
        </div>

        <div className="space-y-3 text-sm">
          <div className="bg-amber-50 dark:bg-amber-950/20 p-3 rounded-lg border border-amber-100 dark:border-amber-900/50 relative">
            <MessageSquare className="h-4 w-4 absolute top-3 right-3 text-amber-500/50" />
            <p className="font-semibold text-amber-800 dark:text-amber-500 mb-1">Customer Complaint</p>
            <p className="text-amber-900/80 dark:text-amber-200/80 italic">"{dispute.customerStatement}"</p>
          </div>

          {dispute.workerResponse ? (
            <div className="bg-blue-50 dark:bg-blue-950/20 p-3 rounded-lg border border-blue-100 dark:border-blue-900/50 relative ml-4">
              <MessageSquare className="h-4 w-4 absolute top-3 right-3 text-blue-500/50" />
              <p className="font-semibold text-blue-800 dark:text-blue-500 mb-1">Worker Response</p>
              <p className="text-blue-900/80 dark:text-blue-200/80 italic">"{dispute.workerResponse}"</p>
            </div>
          ) : (
            <div className="ml-4 p-3 border border-dashed rounded-lg text-muted-foreground text-center text-xs">
              Waiting for worker response...
            </div>
          )}

          {dispute.resolution && (
            <div className="bg-green-50 dark:bg-green-950/20 p-3 rounded-lg border border-green-200 mt-4">
              <p className="font-semibold text-green-800 dark:text-green-500 mb-1 flex items-center gap-2">
                <Scale className="h-4 w-4" /> Resolution
              </p>
              <p className="text-green-900/80 dark:text-green-200/80">{dispute.resolution}</p>
            </div>
          )}
        </div>
      </CardContent>

      {(dispute.status === 'OPEN' || dispute.status === 'UNDER_REVIEW') && (onResolve || onEscalate) && (
        <CardFooter className="flex gap-2 justify-end pt-2 border-t bg-muted/20">
          {onEscalate && (
            <Button variant="outline" className="text-destructive hover:text-destructive" onClick={() => onEscalate(dispute.id)}>
              Escalate to Tribunal
            </Button>
          )}
          {onResolve && (
            <Button onClick={() => onResolve(dispute.id)}>
              Propose Resolution
            </Button>
          )}
        </CardFooter>
      )}
    </Card>
  );
}

import React from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { formatCurrency, formatDate, cn } from "@/lib/utils";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Shield, TrendingUp, IndianRupee } from "lucide-react";

interface Earning {
  id: string;
  date: string | Date;
  description: string;
  gross: number;
  deductions: {
    cooperative: number;
    welfare: number;
  };
  net: number;
}

interface EarningsLedgerProps {
  earnings: Earning[];
  period: string;
  totals: {
    gross: number;
    cooperative: number;
    welfare: number;
    net: number;
