'use client';

import { useEffect, useState } from 'react';
import dynamic from 'next/dynamic';
import 'leaflet/dist/leaflet.css';
import { Card, CardContent } from '@/components/ui/card';
import { Loader2 } from 'lucide-react';

// Next.js dynamic import for Leaflet (must disable SSR for window object)
const MapContainer = dynamic(() => import('react-leaflet').then(m => m.MapContainer), { ssr: false });
const TileLayer = dynamic(() => import('react-leaflet').then(m => m.TileLayer), { ssr: false });
const Marker = dynamic(() => import('react-leaflet').then(m => m.Marker), { ssr: false });
const Popup = dynamic(() => import('react-leaflet').then(m => m.Popup), { ssr: false });

interface LocationMarker {
  lat: number;
  lng: number;
  label: string;
  isWorker?: boolean;
}

export function LiveMap({
  markers,
  height = '300px',
  center,
}: {
  markers: LocationMarker[];
  height?: string;
  center?: [number, number];
}) {
  const [mounted, setMounted] = useState(false);
  const [icons, setIcons] = useState<any>(null);

  useEffect(() => {
    // Only load Leaflet on the client
    setMounted(true);
    
    // Fix Leaflet's default icon path issues in React
    import('leaflet').then((L) => {
      const customerIcon = new L.Icon({
        iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
        iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
        shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
        iconSize: [25, 41],
        iconAnchor: [12, 41],
        popupAnchor: [1, -34],
        shadowSize: [41, 41],
      });

      // Simple red hue shift for worker using filter in CSS, or a different icon. We'll use default.
      const workerIcon = new L.Icon({
        iconUrl: 'https://raw.githubusercontent.com/pointhi/leaflet-color-markers/master/img/marker-icon-2x-red.png',
        shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
        iconSize: [25, 41],
        iconAnchor: [12, 41],
        popupAnchor: [1, -34],
        shadowSize: [41, 41],
      });

      setIcons({ customerIcon, workerIcon });
    });
  }, []);

  if (!mounted || !icons) {
    return (
      <Card>
        <CardContent className={`flex items-center justify-center p-6 border rounded-lg bg-gray-50`} style={{ height }}>
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    );
  }

  // Calculate default center if not provided
  const mapCenter: [number, number] = center || 
    (markers.length > 0 ? [markers[0].lat, markers[0].lng] : [23.0225, 72.5714]); // Default to Ahmedabad

  return (
    <div style={{ height, width: '100%' }} className="rounded-lg overflow-hidden border shadow-sm z-0 relative">
      <MapContainer 
        center={mapCenter} 
        zoom={13} 
        scrollWheelZoom={false} 
        style={{ height: '100%', width: '100%', zIndex: 0 }}
      >
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        {markers.map((m, i) => (
          <Marker 
            key={i} 
            position={[m.lat, m.lng]} 
            icon={m.isWorker ? icons.workerIcon : icons.customerIcon}
          >
            <Popup>{m.label}</Popup>
          </Marker>
        ))}
      </MapContainer>
    </div>
  );
}

"use client";

import React from "react";
import { Bell, Calendar, IndianRupee, MessageSquare, AlertTriangle, CheckCircle2 } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { cn } from "@/lib/utils";

interface NotificationItemProps {
  notification: {
    id: string;
    type: "BOOKING" | "PAYMENT" | "MESSAGE" | "SYSTEM" | "ALERT";
    title: string;
    body: string;
    readAt?: string | Date | null;
    createdAt: string | Date;
  };
  onClick?: () => void;
  className?: string;
}

export function NotificationItem({ notification, onClick, className }: NotificationItemProps) {
  const isUnread = !notification.readAt;

  const getIcon = () => {
    switch (notification.type) {
      case "BOOKING": return <Calendar className="h-4 w-4 text-blue-500" />;
      case "PAYMENT": return <IndianRupee className="h-4 w-4 text-green-500" />;
      case "MESSAGE": return <MessageSquare className="h-4 w-4 text-purple-500" />;
      case "ALERT": return <AlertTriangle className="h-4 w-4 text-amber-500" />;
      case "SYSTEM":
      default: return <Bell className="h-4 w-4 text-slate-500" />;
    }
  };

  return (
    <div 
      onClick={onClick}
      className={cn(
        "flex gap-4 p-4 hover:bg-muted/50 transition-colors cursor-pointer border-b last:border-0",
        isUnread ? "bg-primary/5" : "bg-transparent",
        className
      )}
    >
      <div className={cn(
        "flex h-10 w-10 shrink-0 items-center justify-center rounded-full border bg-background shadow-sm",
        isUnread && "border-primary/50 shadow-primary/10"
      )}>
        {getIcon()}
      </div>
      
      <div className="flex flex-1 flex-col gap-1">
        <div className="flex items-start justify-between gap-2">
          <p className={cn("text-sm font-medium", isUnread && "text-foreground font-semibold")}>
            {notification.title}
          </p>
          <span className="text-xs text-muted-foreground whitespace-nowrap shrink-0 mt-0.5">
            {formatDistanceToNow(new Date(notification.createdAt), { addSuffix: true })}
          </span>
        </div>
        <p className="text-xs text-muted-foreground line-clamp-2">
          {notification.body}
        </p>
      </div>
      
      {isUnread && (
        <div className="flex items-center justify-center w-4 shrink-0">
          <div className="h-2 w-2 rounded-full bg-primary" />
        </div>
      )}
    </div>
  );
}

import React from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { formatCurrency, cn, getStatusColor } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { CreditCard, CheckCircle2, Clock, AlertCircle } from "lucide-react";

interface PaymentSummaryProps {
  payment?: {
    amount?: number;
    method?: string | null;
    status?: string;
    transactionId?: string | null;
  } | any;
  className?: string;
}

export function PaymentSummary({ payment, className }: PaymentSummaryProps) {
  if (!payment) return null;

  const amount = payment.amount || payment.total || 0;
  const method = payment.method || "UPI / Digital";
  const status = payment.status || "COMPLETED";
  const transactionId = payment.transactionId || (status === "PENDING" ? "Pending" : "Not available");

  return (
    <Card className={cn("overflow-hidden bg-white border shadow-xs", className)}>
      <CardHeader className="bg-gray-50/70 pb-3">
        <CardTitle className="text-xs font-bold uppercase tracking-wider text-gray-700 flex items-center justify-between">
          Payment Receipt
          <Badge className={cn("text-xs font-semibold", getStatusColor(status))}>
            {status}
          </Badge>
