                      </div>
                      <p className="text-gray-700">
                        {commentText ? commentText : <span className="italic text-gray-400">No written review</span>}
                      </p>
                      {dateStr && (
                        <p className="text-[10px] text-gray-400">{dateStr}</p>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

